package com.mochikibun.monsthub;
import org.junit.*;
import static org.junit.Assert.*;
import org.json.*;
public class CatalogUsabilityTest {
 private JSONObject character()throws Exception{return new JSONObject().put("id","gw:1").put("name","テストキャラ").put("element","火").put("form","獣神化").put("icon","123");}
 @Test public void newInstallStartsWithZeroAccounts()throws Exception{HubState s=HubState.create();assertEquals(0,s.accounts().length());assertEquals(0,s.totalOrbs());String main=s.addAccount("メイン");String sub=s.addAccount("サブ");assertEquals(2,s.copy().accounts().length());assertNotEquals(main,sub);}
 @Test public void plusMinusIsAccountScopedAndNeverGoesNegative()throws Exception{HubState s=HubState.create();String main=s.addAccount("メイン"),sub=s.addAccount("サブ");JSONObject c=character();assertEquals(1,s.planner().adjustOwned(c,main,1));assertEquals(2,s.planner().adjustOwned(c,main,1));assertEquals(1,s.planner().adjustOwned(c,sub,1));assertEquals(3,s.planner().owned("gw:1",""));assertEquals(1,s.planner().adjustOwned(c,main,-1));assertEquals(0,s.planner().adjustOwned(c,main,-1));assertEquals(0,s.planner().adjustOwned(c,main,-1));assertEquals(1,s.copy().planner().owned("gw:1",sub));}
 @Test public void buttonsDoNotOverwriteTrainingDetails()throws Exception{HubState s=HubState.create();String main=s.addAccount("メイン");JSONObject c=character();s.planner().adjustOwned(c,main,1);JSONObject detail=s.planner().list("inventory").getJSONObject(0);detail.put("fruit","同族加撃L").put("luck",99).put("trained",true);s.planner().adjustOwned(c,main,1);assertEquals(2,s.planner().owned("gw:1",main));assertEquals(2,s.planner().list("inventory").length());s.planner().adjustOwned(c,main,-1);assertEquals(1,s.planner().list("inventory").length());assertEquals("同族加撃L",s.copy().planner().list("inventory").getJSONObject(0).getString("fruit"));}
 @Test public void ambiguousDetailedEntriesRequireChoosingWhichOneToRemove()throws Exception{HubState s=HubState.create();String main=s.addAccount("メイン");JSONObject c=character();s.planner().adjustOwned(c,main,1);s.planner().list("inventory").getJSONObject(0).put("fruit","A");s.planner().adjustOwned(c,main,1);s.planner().list("inventory").getJSONObject(1).put("fruit","B");try{s.planner().adjustOwned(c,main,-1);fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("育成記録が複数"));}assertEquals(2,s.copy().planner().owned("gw:1",main));}
 @Test public void oldRegisteredAccountsAndInventoryRemainOnUpgrade()throws Exception{HubState s=TestStates.twelve();String main=s.accounts().getJSONObject(0).getString("id");s.planner().adjustOwned(character(),main,1);HubState restored=HubState.parse(s.json());assertEquals(12,restored.accounts().length());assertEquals(1,restored.planner().owned("gw:1",main));}
 @Test public void iconRequestsAreRestrictedToKnownCdnTokens(){assertEquals("https://img.gamewith.jp/article_tools/monst/gacha/123.jpg",CatalogIcons.url("123"));assertFalse(CatalogIcons.url("ruisfrois_kai").isEmpty());assertEquals("",CatalogIcons.url("../secret"));assertEquals("",CatalogIcons.url("https://example.com"));}
}
